VZ.live('dpOne',{rng:[['dpOneL','l'],['dpOneB','b']],seg:[['dpOneC','c','free']]},st=>{const L=st.l||22,Bs=st.b||200,chl=(st.c||'free')==='chl';
 const A=axes([120,40,940,320],[0,60],[2,6],{xt:[0,10,20,30,40,50,60],yt:[2,3,4,5,6],yf:v=>'10'+['²','³','⁴','⁵','⁶'][v-2],xl:'время после заражения, мин',yl:'бляшек (БОЕ) в 1 мл'});
 const i0=500,lg=v=>Math.log10(Math.max(1,v));const rise=10;
 const free=x=>x<L?i0:x<L+rise?i0*(1+(Bs-1)*(x-L)/rise):i0*Bs;
 const ecl=Math.max(6,L-10);const intra=x=>x<ecl?i0*0.02:x<L+rise?i0*Math.min(Bs,Math.max(0.02,(Bs)*(x-ecl)/(L+rise-ecl))):i0*Bs;
 let h=A.h+curve(x=>lg(free(x)),0,60,A.sx,A.sy,{c:C.hema,w:3.5,n:240});
 if(chl)h+=curve(x=>lg(Math.max(free(x)*(x<L?0:1),intra(x))),0,60,A.sx,A.sy,{c:C.eosin,w:3,d:'8 6',n:240});
 h+=ln(A.sx(L),40,A.sx(L),320,{c:C.amber,w:2,d:'4 5'})+t(A.sx(L)+6,60,'латентный период '+L+' мин',{s:15,w:700,c:C.amber});
 if(chl)h+=t(A.sx(ecl/2),A.sy(2.3),'эклипс',{s:15,w:700,a:'middle',c:C.eosin});
 return {svg:h,tx:`<b>Выход фага: ${num(i0*Bs,0)} / ${i0} = ${Bs} на клетку</b>В латентный период ни одна заражённая клетка ещё не лопнула, и каждая даёт одну бляшку: число бляшек равно числу заражённых клеток. ${chl?'Пунктир: пробы разрушали хлороформом. В первые минуты (эклипс) готовых фагов внутри нет вовсе, только ДНК и белки; потом число внутриклеточных фагов растёт раньше, чем клетки начинают лопаться.':'Включи «хлороформ», чтобы увидеть фаги внутри клеток.'}`}});

